macro_rules! deps {
    () => {
        Interner!();
        GenericArgs!();
        AdtDef!();
        FnSigTys!();
        Const!();
        FnHeader!();
        AliasTy!();
        DynKind!();
        InferTy!();
        BoundExistentialPredicates!();
        Tys!();
        AliasTyKind!();
        Ty!();
        UnsafeBinderInner!();
        Region!();
        DefId!();
        Binder!();
    };
}

macro_rules! TyKind {
    () => {
        deps!();
        # [doc = " Defines the kinds of types used by the type system."] # [doc = ""] # [doc = " Types written by the user start out as `hir::TyKind` and get"] # [doc = " converted to this representation using `<dyn HirTyLowerer>::lower_ty`."] # [cfg_attr (feature = "nightly" , rustc_diagnostic_item = "IrTyKind")] # [derive_where (Clone , Copy , Hash , PartialEq ; I : Interner)] # [cfg_attr (feature = "nightly" , derive (Encodable_NoContext , Decodable_NoContext , HashStable_NoContext))] pub enum TyKind < I : Interner > { # [doc = " The primitive boolean type. Written as `bool`."] Bool , # [doc = " The primitive character type; holds a Unicode scalar value"] # [doc = " (a non-surrogate code point). Written as `char`."] Char , # [doc = " A primitive signed integer type. For example, `i32`."] Int (IntTy) , # [doc = " A primitive unsigned integer type. For example, `u32`."] Uint (UintTy) , # [doc = " A primitive floating-point type. For example, `f64`."] Float (FloatTy) , # [doc = " Algebraic data types (ADT). For example: structures, enumerations and unions."] # [doc = ""] # [doc = " For example, the type `List<i32>` would be represented using the `AdtDef`"] # [doc = " for `struct List<T>` and the args `[i32]`."] # [doc = ""] # [doc = " Note that generic parameters in fields only get lazily instantiated"] # [doc = " by using something like `adt_def.all_fields().map(|field| field.ty(interner, args))`."] Adt (I :: AdtDef , I :: GenericArgs) , # [doc = " An unsized FFI type that is opaque to Rust. Written as `extern type T`."] Foreign (I :: ForeignId) , # [doc = " The pointee of a string slice. Written as `str`."] Str , # [doc = " An array with the given length. Written as `[T; N]`."] Array (I :: Ty , I :: Const) , # [doc = " A pattern newtype. Takes any type and restricts its valid values to its pattern."] # [doc = " This will also change the layout to take advantage of this restriction."] # [doc = " Only `Copy` and `Clone` will automatically get implemented for pattern types."] # [doc = " Auto-traits treat this as if it were an aggregate with a single nested type."] # [doc = " Only supports integer range patterns for now."] Pat (I :: Ty , I :: Pat) , # [doc = " The pointee of an array slice. Written as `[T]`."] Slice (I :: Ty) , # [doc = " A raw pointer. Written as `*mut T` or `*const T`"] RawPtr (I :: Ty , Mutability) , # [doc = " A reference; a pointer with an associated lifetime. Written as"] # [doc = " `&'a mut T` or `&'a T`."] Ref (I :: Region , I :: Ty , Mutability) , # [doc = " The anonymous type of a function declaration/definition. Each"] # [doc = " function has a unique type."] # [doc = ""] # [doc = " For the function `fn foo() -> i32 { 3 }` this type would be"] # [doc = " shown to the user as `fn() -> i32 {foo}`."] # [doc = ""] # [doc = " For example the type of `bar` here:"] # [doc = " ```rust"] # [doc = " fn foo() -> i32 { 1 }"] # [doc = " let bar = foo; // bar: fn() -> i32 {foo}"] # [doc = " ```"] FnDef (I :: FunctionId , I :: GenericArgs) , # [doc = " A pointer to a function. Written as `fn() -> i32`."] # [doc = ""] # [doc = " Note that both functions and closures start out as either"] # [doc = " [FnDef] or [Closure] which can be then be coerced to this variant."] # [doc = ""] # [doc = " For example the type of `bar` here:"] # [doc = ""] # [doc = " ```rust"] # [doc = " fn foo() -> i32 { 1 }"] # [doc = " let bar: fn() -> i32 = foo;"] # [doc = " ```"] # [doc = ""] # [doc = " These two fields are equivalent to a `ty::Binder<I, FnSig<I>>`. But by"] # [doc = " splitting that into two pieces, we get a more compact data layout that"] # [doc = " reduces the size of `TyKind` by 8 bytes. It is a very hot type, so it's"] # [doc = " worth the mild inconvenience."] FnPtr (ty :: Binder < I , FnSigTys < I > > , FnHeader < I >) , # [doc = " An unsafe binder type."] # [doc = ""] # [doc = " A higher-ranked type used to represent a type which has had some of its"] # [doc = " lifetimes erased. This can be used to represent types in positions where"] # [doc = " a lifetime is literally inexpressible, such as self-referential types."] UnsafeBinder (UnsafeBinderInner < I >) , # [doc = " A trait object. Written as `dyn for<'b> Trait<'b, Assoc = u32> + Send + 'a`."] Dynamic (I :: BoundExistentialPredicates , I :: Region , DynKind) , # [doc = " The anonymous type of a closure. Used to represent the type of `|a| a`."] # [doc = ""] # [doc = " Closure args contain both the - potentially instantiated - generic parameters"] # [doc = " of its parent and some synthetic parameters. See the documentation for"] # [doc = " `ClosureArgs` for more details."] Closure (I :: ClosureId , I :: GenericArgs) , # [doc = " The anonymous type of a closure. Used to represent the type of `async |a| a`."] # [doc = ""] # [doc = " Coroutine-closure args contain both the - potentially instantiated - generic"] # [doc = " parameters of its parent and some synthetic parameters. See the documentation"] # [doc = " for `CoroutineClosureArgs` for more details."] CoroutineClosure (I :: CoroutineClosureId , I :: GenericArgs) , # [doc = " The anonymous type of a coroutine. Used to represent the type of"] # [doc = " `|a| yield a`."] # [doc = ""] # [doc = " For more info about coroutine args, visit the documentation for"] # [doc = " `CoroutineArgs`."] Coroutine (I :: CoroutineId , I :: GenericArgs) , # [doc = " A type representing the types stored inside a coroutine."] # [doc = " This should only appear as part of the `CoroutineArgs`."] # [doc = ""] # [doc = " Unlike upvars, the witness can reference lifetimes from"] # [doc = " inside of the coroutine itself. To deal with them in"] # [doc = " the type of the coroutine, we convert them to higher ranked"] # [doc = " lifetimes bound by the witness itself."] # [doc = ""] # [doc = " This contains the `DefId` and the `GenericArgsRef` of the coroutine."] # [doc = " The actual witness types are computed on MIR by the `mir_coroutine_witnesses` query."] # [doc = ""] # [doc = " Looking at the following example, the witness for this coroutine"] # [doc = " may end up as something like `for<'a> [Vec<i32>, &'a Vec<i32>]`:"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(coroutines)]"] # [doc = " #[coroutine] static |a| {"] # [doc = "     let x = &vec![3];"] # [doc = "     yield a;"] # [doc = "     yield x[0];"] # [doc = " }"] # [doc = " # ;"] # [doc = " ```"] CoroutineWitness (I :: CoroutineId , I :: GenericArgs) , # [doc = " The never type `!`."] Never , # [doc = " A tuple type. For example, `(i32, bool)`."] Tuple (I :: Tys) , # [doc = " A projection, opaque type, free type alias, or inherent associated type."] # [doc = " All of these types are represented as pairs of def-id and args, and can"] # [doc = " be normalized, so they are grouped conceptually."] Alias (AliasTyKind , AliasTy < I >) , # [doc = " A type parameter; for example, `T` in `fn f<T>(x: T) {}`."] Param (I :: ParamTy) , # [doc = " Bound type variable, used to represent the `'a` in `for<'a> fn(&'a ())`."] # [doc = ""] # [doc = " For canonical queries, we replace inference variables with bound variables,"] # [doc = " so e.g. when checking whether `&'_ (): Trait<_>` holds, we canonicalize that to"] # [doc = " `for<'a, T> &'a (): Trait<T>` and then convert the introduced bound variables"] # [doc = " back to inference variables in a new inference context when inside of the query."] # [doc = ""] # [doc = " It is conventional to render anonymous bound types like `^N` or `^D_N`,"] # [doc = " where `N` is the bound variable's anonymous index into the binder, and"] # [doc = " `D` is the debruijn index, or totally omitted if the debruijn index is zero."] # [doc = ""] # [doc = " See the `rustc-dev-guide` for more details about"] # [doc = " [higher-ranked trait bounds][1] and [canonical queries][2]."] # [doc = ""] # [doc = " [1]: https://rustc-dev-guide.rust-lang.org/traits/hrtb.html"] # [doc = " [2]: https://rustc-dev-guide.rust-lang.org/traits/canonical-queries.html"] Bound (DebruijnIndex , I :: BoundTy) , # [doc = " A placeholder type, used during higher ranked subtyping to instantiate"] # [doc = " bound variables."] # [doc = ""] # [doc = " It is conventional to render anonymous placeholder types like `!N` or `!U_N`,"] # [doc = " where `N` is the placeholder variable's anonymous index (which corresponds"] # [doc = " to the bound variable's index from the binder from which it was instantiated),"] # [doc = " and `U` is the universe index in which it is instantiated, or totally omitted"] # [doc = " if the universe index is zero."] Placeholder (I :: PlaceholderTy) , # [doc = " A type variable used during type checking."] # [doc = ""] # [doc = " Similar to placeholders, inference variables also live in a universe to"] # [doc = " correctly deal with higher ranked types. Though unlike placeholders,"] # [doc = " that universe is stored in the `InferCtxt` instead of directly"] # [doc = " inside of the type."] Infer (InferTy) , # [doc = " A placeholder for a type which could not be computed; this is"] # [doc = " propagated to avoid useless error messages."] Error (I :: ErrorGuaranteed) , }
    };
}

TyKind!();